import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.PU0FRLnN.js";import"./chunks/assets.BHTds6ax.js";var i=JSON.parse(`{"title":"Ways to Export","description":"","frontmatter":{},"headers":[],"relativePath":"guide/exporting.md","filePath":"guide/exporting.md"}`),a={name:`guide/exporting.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="ways-to-export" tabindex="-1">Ways to Export <a class="header-anchor" href="#ways-to-export" aria-label="Permalink to “Ways to Export”">​</a></h1><p>There are <strong>four ways</strong> to export with GraphScribe. Start with whichever matches what you&#39;re doing.</p><h2 id="_1-export-a-single-asset" tabindex="-1">1. Export a single asset <a class="header-anchor" href="#_1-export-a-single-asset" aria-label="Permalink to “1. Export a single asset”">​</a></h2><ul><li>Open a Blueprint or Widget Blueprint → click <strong>GraphScribe</strong> in the toolbar → the export dialog opens with a live preview → <strong>Copy</strong> or <strong>Save As...</strong>.</li><li>DataAssets don&#39;t have a Blueprint toolbar: right-click the asset in the Content Browser → <strong>Export with GraphScribe...</strong>.</li><li>Works on Blueprints, Widget Blueprints, and DataAssets.</li></ul><p><img src="/GraphScribe-Docs/img/single-asset-export-menu.png" alt="The single-asset export dialog" width="848" height="909"></p><h2 id="_2-export-selected-nodes-only" tabindex="-1">2. Export selected nodes only <a class="header-anchor" href="#_2-export-selected-nodes-only" aria-label="Permalink to “2. Export selected nodes only”">​</a></h2><p>Sometimes you only want part of a graph, a snippet for a PR, a doc, or a question.</p><ol><li>Select some nodes inside a graph.</li><li>Right-click → <strong>Export Selection with GraphScribe...</strong></li></ol><p>Snippet exports are smaller and focused:</p><ul><li>they include the selected nodes plus the owning function&#39;s entry,</li><li>collapsed composite nodes expand to include their inner graph nodes,</li><li>they intentionally <strong>omit</strong> variables, widget trees, and class references.</li></ul><p><img src="/GraphScribe-Docs/img/selection-export-context.png" alt="Selected nodes and the Export Selection context menu entry" width="1384" height="801"></p><h2 id="_3-export-a-whole-folder" tabindex="-1">3. Export a whole folder <a class="header-anchor" href="#_3-export-a-whole-folder" aria-label="Permalink to “3. Export a whole folder”">​</a></h2><p>This is the option for documenting a feature or your whole project, and the mode you&#39;ll use most with AI tooling.</p><ol><li>In the Content Browser, right-click one or more folders → <strong>Export Blueprints with GraphScribe...</strong>.</li><li>A batch dialog (<strong>GraphScribe Export Folder</strong>) opens showing: <ul><li>the selected <strong>content path(s)</strong>,</li><li>the <strong>Format</strong> combo,</li><li>an <strong>Include subfolders</strong> checkbox (on by default),</li><li>a live count, <em>Found N Blueprint asset(s) to export</em>,</li><li>the <strong>Output directory</strong> (pre-filled with your configured save directory) with a <strong>Browse...</strong> button.</li></ul></li><li>Click <strong>Export</strong>. GraphScribe exports every supported asset with the selected format and writes a log (<code>Exported:</code> / <code>Failed:</code> / <code>Skipped:</code> counts, skipped assets, and every written file) plus a toast notification.</li></ol><p><img src="/GraphScribe-Docs/img/content-browser-export-menu.png" alt="Content Browser context menu with the GraphScribe export entries" width="791" height="761"><img src="/GraphScribe-Docs/img/batch-log-complete.png" alt="The batch export dialog with a completed export log" width="1232" height="624"></p><p>Notes:</p><ul><li>Output files mirror your Content structure: <code>/Game/Foo/Bar.BP_X</code> → <code>&lt;Output Directory&gt;/Foo/Bar/BP_X.&lt;ext&gt;</code>.</li><li>DataTables are never gathered, Blueprints that can&#39;t be exported (e.g. interface/macro-only assets) are listed under <em>Skipped</em>.</li><li>If you chose <strong>Graphify</strong>, the run also rebuilds <strong><code>ProjectLinkage.graphify.json</code></strong> at the root of the output directory, a single project-wide graph merged from every <code>*.graphify.json</code> already under that directory (so folder-by-folder exports accumulate). See <a href="/GraphScribe-Docs/guide/graphify-output.html">Graphify: AI-Ready Graphs</a>.</li></ul><h2 id="where-do-files-go" tabindex="-1">Where do files go? <a class="header-anchor" href="#where-do-files-go" aria-label="Permalink to “Where do files go?”">​</a></h2><ul><li><strong>Single asset:</strong> you choose the location in the <strong>Save As...</strong> dialog, pre-filled with the directory configured in <a href="/GraphScribe-Docs/guide/settings.html">Project Settings</a>.</li><li><strong>Folder batch:</strong> the <strong>Output directory</strong> field in the batch dialog (pre-filled from the same setting).</li><li><strong>Selection:</strong> same as single asset.</li></ul>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};